blocks.text:
/* .box ha larghezza 100% su schermi minori di 768 px */
@media only screen and (max-width: 768px) {
  .box { width: 100%; }
}
/* .box ha larghezza 400px su schermi maggiori di 768 px */
@media only screen and (min-width: 768px) {
  .box { width: 400px; }
}

